import React, { useEffect, useState } from 'react';
import type { DeliverySlot } from '../../types';
import { api } from '../../services/api';
import { Button } from '../common/Button';
import { Skeleton } from '../common/Skeleton';
import { ErrorState } from '../common/ErrorState';
import { Clock, Sunrise, Sun, Sunset, Snowflake } from 'lucide-react';

interface SlotStepProps {
  selectedSlotId: string;
  onSelectSlot: (slot: DeliverySlot) => void;
  onProceed: () => void;
  onBack: () => void;
}

const FALLBACK_ICON = Clock;

/**
 * Slot windows are generated by the server from the kitchen's delivery settings
 * and its order cut-off time. Nothing is hardcoded on the client.
 */
export const SlotStep: React.FC<SlotStepProps> = ({
  selectedSlotId,
  onSelectSlot,
  onProceed,
  onBack,
}) => {
  const [slots, setSlots] = useState<DeliverySlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    let active = true;
    setLoading(true);
    setError(null);
    api
      .getDeliverySlots()
      .then((nextSlots) => {
        if (!active) return;
        setSlots(nextSlots);
        if (nextSlots.length > 0 && !nextSlots.some((slot) => slot.id === selectedSlotId)) {
          onSelectSlot(nextSlots[0]);
        }
      })
      .catch((err) => {
        if (!active) return;
        setError(err instanceof Error ? err.message : 'Delivery slots could not be loaded.');
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reloadKey]);

  return (
    <div className="bg-white rounded-3xl border border-stone-200/90 p-5 sm:p-6 shadow-xs space-y-5">
      <div className="pb-3 border-b border-stone-100">
        <h3 className="text-base sm:text-lg font-bold text-[#4A2C17] font-heading">
          Choose Delivery Slot
        </h3>
        <p className="text-xs text-stone-500">
          Slots are shown for serviceable pincodes based on the kitchen’s daily cut-off.
        </p>
      </div>

      {loading && (
        <div className="space-y-3">
          {[1, 2, 3].map((index) => (
            <Skeleton key={index} className="h-20 w-full rounded-2xl" />
          ))}
        </div>
      )}

      {!loading && error && (
        <ErrorState
          title="Delivery slots unavailable"
          message={error}
          onRetry={() => setReloadKey((key) => key + 1)}
        />
      )}

      {!loading && !error && slots.length === 0 && (
        <p className="p-4 rounded-2xl bg-amber-50 border border-amber-200 text-xs text-amber-900">
          No delivery slots are open right now. Please check back later or contact customer care.
        </p>
      )}

      {!loading && !error && slots.length > 0 && (
        <div className="space-y-3">
          {slots.map((slot) => {
            const isSelected = selectedSlotId === slot.id;
            const title = slot.title.toLowerCase();
            const SlotIcon = title.includes('morning')
              ? Sunrise
              : title.includes('evening') || title.includes('night')
              ? Sunset
              : title.includes('afternoon')
              ? Sun
              : FALLBACK_ICON;

            return (
              <button
                key={slot.id}
                type="button"
                disabled={!slot.isAvailable}
                onClick={() => onSelectSlot(slot)}
                className={`w-full text-left p-4 rounded-2xl border transition-all flex items-center justify-between gap-3 ${
                  isSelected
                    ? 'border-amber-500 bg-amber-50/50 ring-2 ring-amber-500/10'
                    : 'border-stone-200 hover:border-amber-300 bg-white'
                } ${!slot.isAvailable ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <div className="flex items-center gap-3.5">
                  <div
                    className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      isSelected ? 'bg-amber-500 text-stone-950' : 'bg-stone-100 text-stone-600'
                    }`}
                  >
                    <SlotIcon className="w-5 h-5" />
                  </div>

                  <div>
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-bold text-sm text-[#4A2C17]">{slot.title}</span>
                      {slot.tag && (
                        <span className="text-[10px] font-bold text-emerald-800 bg-emerald-50 px-2 py-0.5 rounded-full border border-emerald-200">
                          {slot.tag}
                        </span>
                      )}
                      {!slot.isAvailable && (
                        <span className="text-[10px] font-bold text-red-700 bg-red-50 px-2 py-0.5 rounded-full border border-red-200">
                          Closed
                        </span>
                      )}
                    </div>
                    <div className="flex items-center gap-2 text-xs text-stone-500 mt-0.5">
                      <Clock className="w-3.5 h-3.5" />
                      <span className="font-semibold text-stone-700">{slot.date}</span>
                      <span>•</span>
                      <span className="font-mono text-stone-600">{slot.timeWindow}</span>
                    </div>
                  </div>
                </div>

                <div
                  className={`w-5 h-5 rounded-full border flex items-center justify-center shrink-0 ${
                    isSelected ? 'border-amber-600 bg-amber-600' : 'border-stone-300'
                  }`}
                >
                  {isSelected && <div className="w-2 h-2 rounded-full bg-white" />}
                </div>
              </button>
            );
          })}
        </div>
      )}

      <div className="p-3.5 rounded-2xl bg-sky-50 border border-sky-100 flex items-center gap-2.5 text-xs text-sky-900">
        <Snowflake className="w-4 h-4 text-sky-600 shrink-0" />
        <span>Dairy items are packed in insulated carriers for the selected window.</span>
      </div>

      <div className="pt-3 border-t border-stone-100 flex items-center justify-between">
        <Button variant="ghost" size="md" onClick={onBack}>
          Back to Address
        </Button>
        <Button
          variant="gold"
          size="md"
          disabled={!selectedSlotId || loading || Boolean(error)}
          onClick={onProceed}
        >
          Continue to Payment
        </Button>
      </div>
    </div>
  );
};
